// Deterministic scheduling only: actual fs operations and unmodified lock module.
// Delay A before/after its rename to model process scheduling in the reap window.
import * as fs from 'node:fs/promises';
import {mock} from 'node:test';
import {AsyncLocalStorage} from 'node:async_hooks';
import {spawn} from 'node:child_process';
const base='/tmp/codex-tool-runs/svton/m2-final-20260930';
const dir=await fs.mkdtemp(base+'/reap-race-'),file=dir+'/state.json',lock=file+'.lock';
const dead=spawn(process.execPath,['-e','process.exit(0)']);await new Promise(r=>dead.on('exit',r));
await fs.writeFile(lock,`${dead.pid}\tdead-owner-token\n`);
const deferred=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve}};
const beforeRename=deferred(),continueRename=deferred(),afterRename=deferred(),continueAfter=deferred();
const bEntered=deferred(),cEntered=deferred(),releaseB=deferred(),releaseC=deferred();
const actor=new AsyncLocalStorage();let hooked=false,bActive=false,cActive=false,overlap=false;
const {default:ignored,...named}=fs;
mock.module('node:fs/promises',{namedExports:{...named,rename:async(from,to)=>{
 if(actor.getStore()==='A'&&from===lock&&!hooked){
  hooked=true;beforeRename.resolve();await continueRename.promise;
  await fs.rename(from,to);afterRename.resolve();await continueAfter.promise;return;
 }
 return fs.rename(from,to);
}}});
const {withFileLock}=await import('/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js');
const a=actor.run('A',()=>withFileLock(file,async()=>{}, {timeoutMs:500})).then(()=>({ok:true}),e=>({ok:false,error:e.message}));
await beforeRename.promise;
const b=actor.run('B',()=>withFileLock(file,async()=>{bActive=true;bEntered.resolve();await releaseB.promise;bActive=false;}));
await bEntered.promise;
continueRename.resolve();await afterRename.promise;
const c=actor.run('C',()=>withFileLock(file,async()=>{cActive=true;overlap=bActive;cEntered.resolve();await releaseC.promise;cActive=false;}));
await cEntered.promise;continueAfter.resolve();const aResult=await a;
const result={deadOwnerPid:dead.pid,scheduledDelaysOnly:true,bAndCOverlap:overlap,bActive,cActive,aResult,reapFiles:(await fs.readdir(dir)).filter(x=>x.includes('.reap-')).length};
releaseB.resolve();await b;releaseC.resolve();await c;
await fs.writeFile(base+'/lock-reap-results.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
mock.restoreAll();

