import * as fs from 'node:fs/promises';
import {createServer} from 'node:https';
import {request} from 'node:http';
import {spawn} from 'node:child_process';
const root='/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit';
const base='/tmp/codex-tool-runs/svton/m2-final-20260930';
process.env.PATH=base+'/bin:'+process.env.PATH;
const {startAgent}=await import(root+'/dist/agent/server.js');
const {SecurityStore}=await import(root+'/dist/agent/security.js');
const work=await fs.mkdtemp(base+'/tls-work-');
const agent=await startAgent({role:'both',token:'FAKE_TLS_MASTER',host:'127.0.0.1',port:0,workRoot:work});
const proxy=createServer({key:await fs.readFile(base+'/tls/key.pem'),cert:await fs.readFile(base+'/tls/cert.pem')},(req,res)=>{
 const upstream=request(agent.url+req.url,{method:req.method,headers:req.headers},r=>{res.writeHead(r.statusCode,r.headers);r.pipe(res)});
 upstream.on('error',()=>{res.writeHead(502);res.end()});req.pipe(upstream);
});
await new Promise(r=>proxy.listen(0,'127.0.0.1',r));
const url='https://127.0.0.1:'+proxy.address().port;
const home=await fs.mkdtemp(base+'/tls-home-');
async function cli(args,cwd=home){return new Promise(resolve=>{const env={...process.env,HOME:home};delete env.NODE_EXTRA_CA_CERTS;delete env.NODE_TLS_REJECT_UNAUTHORIZED;const c=spawn(process.execPath,[root+'/dist/cli/main.js',...args],{cwd,env});let stdout='',stderr='';c.stdout.on('data',d=>stdout+=d);c.stderr.on('data',d=>stderr+=d);c.on('close',code=>resolve({code,stdout,stderr}));});}
await fs.copyFile(base+'/tls/cert.pem',home+'/ca.pem');
const s=new SecurityStore(work+'/security.json');await s.load();
const c=await s.createCode('builder',15);
const pair=await cli(['pair',url,'--code',c.code,'--name','builder','--ca-file','./ca.pem','--json']);
const rc=await s.createCode('runtime',15);
const rp=await cli(['pair',url,'--code',rc.code,'--name','staging','--ca-file','./ca.pem','--json']);
await fs.writeFile(home+'/ship.config.json',JSON.stringify({builder:{mode:'static',static:{url,tokenRef:'builder'}},runtime:{targets:{staging:{url,tokenRef:'staging'}}},registry:{url:'127.0.0.1:5001',namespace:'audit'}}));
const doctor=await cli(['doctor','--json']);
const other=await fs.mkdtemp(base+'/tls-other-project-');
const elsewhere=await cli(['doctor','--config',home+'/ship.config.json','--json'],other);
const result={pairExit:pair.code,runtimePairExit:rp.code,pairOutput:JSON.parse(pair.stdout),doctorExit:doctor.code,doctorOutput:JSON.parse(doctor.stdout),elsewhereExit:elsewhere.code,elsewhereOutput:JSON.parse(elsewhere.stdout),failed:pair.code===0&&doctor.code===0&&elsewhere.code!==0};
await fs.writeFile(base+'/tls-results.json',JSON.stringify(result,null,2));
console.log(JSON.stringify({pairExit:pair.code,doctorExit:doctor.code,elsewhereExit:elsewhere.code,failed:result.failed}));
proxy.closeAllConnections();await new Promise(r=>proxy.close(r));await agent.close();

